from decimal import Decimal, ROUND_HALF_UP

CENTS = Decimal('0.01')


def _round_cents(value):
    return value.quantize(CENTS, rounding=ROUND_HALF_UP)


def _fmt(value):
    value = _round_cents(value)
    if value == 0:
        value = value.copy_abs()
    return f'{value:.2f}'


def invoice(lines, tax_rate):
    rate = Decimal(tax_rate)
    subtotal = Decimal('0')
    tax = Decimal('0')
    for row in lines:
        line_total = _round_cents(Decimal(row['unit_price']) * row['qty'])
        subtotal += line_total
        if row['taxable']:
            tax += _round_cents(line_total * rate)
    return {
        'subtotal': _fmt(subtotal),
        'tax': _fmt(tax),
        'total': _fmt(subtotal + tax),
    }
